import Foundation

#if !EMBRACE_COCOAPOD_BUILDING_SDK
    import EmbraceSemantics
    import EmbraceConfiguration
    import EmbraceCommonInternal
#endif

class DefaultOtelSignalsLimiter: OTelSignalsLimiter {

    static let emptyType = "__emb.empty__"

    /// Counters of the signals generated by a single source during the current session.
    struct Counters {
        var customSpanCounter = 0
        var eventCounter = 0
        var eventTypeCounter: [String: UInt] = [:]
        var linkCounter = 0
        var logCounter: [Int: UInt] = [:]
    }

    struct MutableState {
        var limits = SessionLimits()

        /// Each source has its own counters so they don't consume each other's budget.
        var user = Counters()
        var captureService = Counters()
    }
    var state = EmbraceMutex(MutableState())

    let notificationCenter: NotificationCenter

    init(
        sessionLimits: SessionLimits = SessionLimits(),
        spanEventTypeLimits: SpanEventTypeLimits = SpanEventTypeLimits(),
        logSeverityLimits: LogSeverityLimits = LogSeverityLimits(),
        configNotificationCenter: NotificationCenter = .default
    ) {
        state.withLock {
            // Limits from the remote config only apply to user signals.
            $0.limits = sessionLimits
            $0.limits.user.events.typeLimits = spanEventTypeLimits
            $0.limits.user.logs.severityLimits = logSeverityLimits
        }
        self.notificationCenter = configNotificationCenter

        notificationCenter.addObserver(
            self,
            selector: #selector(onConfigUpdated),
            name: .embraceConfigUpdated,
            object: nil
        )
    }

    deinit {
        notificationCenter.removeObserver(self)
    }

    @objc func onConfigUpdated(notification: Notification) {
        guard let config = notification.object as? EmbraceConfigurable else {
            return
        }

        state.withLock {
            // Limits from the remote config only apply to user signals.
            $0.limits.user.events.typeLimits = config.spanEventTypeLimits
            $0.limits.user.logs.severityLimits = config.logSeverityLimits
        }
    }

    func reset() {
        state.withLock {
            $0.user = Counters()
            $0.captureService = Counters()
        }
    }

    func shouldCreateCustomSpan(source: EmbraceOTelSignalSource) -> Bool {
        return withLimits(for: source) { limits, counters in
            if counters.customSpanCounter < limits.customSpans.count {
                counters.customSpanCounter += 1
                return true
            }

            return false
        }
    }

    func shouldAddSessionEvent(ofType type: EmbraceType?, source: EmbraceOTelSignalSource) -> Bool {
        return withLimits(for: source) { limits, counters in
            // check total limit
            if counters.eventCounter >= limits.events.sessionSpanEventCount {
                return false
            }

            // check limit for event type
            let type = type?.rawValue ?? Self.emptyType

            guard let typeLimits = limits.events.typeLimits else {
                counters.eventCounter += 1
                return true
            }

            // apply limit
            let limit = limitForEventType(type, limits: typeLimits)
            var result = false

            var count = counters.eventTypeCounter[type] ?? 0
            if count < limit {
                counters.eventCounter += 1
                count += 1
                result = true
            }
            counters.eventTypeCounter[type] = count

            return result
        }
    }

    func shouldCreateLog(type: EmbraceType, severity: EmbraceLogSeverity, source: EmbraceOTelSignalSource) -> Bool {
        // no limits for internal, crash or hang logs
        guard type != .internal && type != .crash && type != .hang else {
            return true
        }

        return withLimits(for: source) { limits, counters in
            // check limit for severity type
            let level = consolidatedSeverity(severity)
            let limit = limitForLogSeverity(level, limits: limits.logs.severityLimits)

            // apply limit
            var result = false

            var count = counters.logCounter[level.rawValue] ?? 0
            if count < limit {
                count += 1
                result = true
            }
            counters.logCounter[level.rawValue] = count

            return result
        }
    }

    func shouldAddSpanEvent(currentCount count: Int, source: EmbraceOTelSignalSource) -> Bool {
        return withLimits(for: source) { limits, _ in
            count < limits.events.customSpanEventCount
        }
    }

    func shouldAddSpanLink(currentCount count: Int, source: EmbraceOTelSignalSource) -> Bool {
        return withLimits(for: source) { limits, _ in
            count < limits.links.customSpanLinkCount
        }
    }

    func shouldAddSpanAttribute(currentCount count: Int, source: EmbraceOTelSignalSource) -> Bool {
        return withLimits(for: source) { limits, _ in
            count < limits.customSpans.attributeCount
        }
    }

    /// Runs `block` under the lock with the limits and counters of the given source.
    /// Sources without limits are always allowed and `block` is not called.
    private func withLimits(
        for source: EmbraceOTelSignalSource,
        _ block: (SignalLimits, inout Counters) -> Bool
    ) -> Bool {
        return state.withLock {
            guard let limits = $0.limits.limits(for: source) else {
                return true
            }

            switch source {
            case .user: return block(limits, &$0.user)
            case .captureService: return block(limits, &$0.captureService)
            case .sdk: return true
            }
        }
    }

    // MARK: Private
    private func limitForEventType(_ type: String, limits: SpanEventTypeLimits) -> UInt {
        if type == EmbraceType.breadcrumb.rawValue {
            return limits.breadcrumb
        }

        return UInt.max
    }

    private func consolidatedSeverity(_ severity: EmbraceLogSeverity) -> EmbraceLogSeverity {
        switch severity {
        case .warn: return .warn
        case .error, .fatal: return .error
        default: return .info
        }
    }

    private func limitForLogSeverity(_ severity: EmbraceLogSeverity, limits: LogSeverityLimits) -> UInt {
        if severity == .warn {
            return limits.warn
        }

        if severity == .error || severity == .fatal {
            return limits.error
        }

        return limits.info
    }
}
